-- SchoolBD_PlatformDB schema (PostgreSQL). Tenant registry for multi-tenant mode.
-- Generated from SMS.DB/Platform/PlatformDbContext.cs (Database.GenerateCreateScript), made idempotent.
-- Run against the EMPTY platform database (e.g. SchoolBD_PlatformDB), not a school database.
-- Safe to re-run.
-- Alternative: `SMS_App platform init` creates the same tables.

CREATE TABLE IF NOT EXISTS "DatabaseServers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ServerName" character varying(100) NOT NULL,
    "Provider" integer NOT NULL,
    "Host" character varying(253) NOT NULL,
    "Port" integer NULL,
    "ConnectionOptions" character varying(500) NULL,
    "SecretReference" character varying(200) NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_DatabaseServers" PRIMARY KEY ("Id")
);


CREATE TABLE IF NOT EXISTS "PlatformAuditLogs" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NULL,
    "Action" character varying(100) NOT NULL,
    "Details" text NULL,
    "Actor" character varying(200) NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_PlatformAuditLogs" PRIMARY KEY ("Id")
);


CREATE TABLE IF NOT EXISTS "PlatformSecrets" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(150) NOT NULL,
    "Ciphertext" text NOT NULL,
    "KeyVersion" integer NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "UpdatedAt" timestamp without time zone NULL,
    CONSTRAINT "PK_PlatformSecrets" PRIMARY KEY ("Id")
);


CREATE TABLE IF NOT EXISTS "Tenants" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantCode" character varying(63) NOT NULL,
    "TenantName" character varying(200) NOT NULL,
    "DisplayName" character varying(200) NULL,
    "Status" integer NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "UpdatedAt" timestamp without time zone NULL,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Tenants" PRIMARY KEY ("Id")
);


CREATE TABLE IF NOT EXISTS "TenantDatabaseConnections" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "DatabaseServerId" integer NOT NULL,
    "DatabaseName" character varying(128) NOT NULL,
    "SecretReference" character varying(200) NOT NULL,
    "IsPrimary" boolean NOT NULL,
    "SchemaVersion" character varying(50) NULL,
    "Status" integer NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "UpdatedAt" timestamp without time zone NULL,
    CONSTRAINT "PK_TenantDatabaseConnections" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TenantDatabaseConnections_DatabaseServers_DatabaseServerId" FOREIGN KEY ("DatabaseServerId") REFERENCES "DatabaseServers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_TenantDatabaseConnections_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id") ON DELETE RESTRICT
);


CREATE TABLE IF NOT EXISTS "TenantDomains" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "Domain" character varying(253) NOT NULL,
    "DomainType" integer NOT NULL,
    "IsPrimary" boolean NOT NULL,
    "IsVerified" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "VerificationToken" character varying(100) NULL,
    "VerifiedAt" timestamp without time zone NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_TenantDomains" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_TenantDomains_ActiveRequiresVerified" CHECK ("IsActive" = false OR "IsVerified" = true),
    CONSTRAINT "FK_TenantDomains_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id") ON DELETE RESTRICT
);


CREATE UNIQUE INDEX IF NOT EXISTS "IX_DatabaseServers_ServerName" ON "DatabaseServers" ("ServerName");


CREATE INDEX IF NOT EXISTS "IX_PlatformAuditLogs_TenantId_CreatedAt" ON "PlatformAuditLogs" ("TenantId", "CreatedAt");


CREATE UNIQUE INDEX IF NOT EXISTS "IX_PlatformSecrets_Name" ON "PlatformSecrets" ("Name");


CREATE UNIQUE INDEX IF NOT EXISTS "IX_TenantDatabaseConnections_DatabaseServerId_DatabaseName" ON "TenantDatabaseConnections" ("DatabaseServerId", "DatabaseName");


CREATE UNIQUE INDEX IF NOT EXISTS "IX_TenantDatabaseConnections_OnePrimaryPerTenant" ON "TenantDatabaseConnections" ("TenantId") WHERE "IsPrimary" = true;


CREATE UNIQUE INDEX IF NOT EXISTS "IX_TenantDomains_Domain" ON "TenantDomains" ("Domain");


CREATE INDEX IF NOT EXISTS "IX_TenantDomains_TenantId" ON "TenantDomains" ("TenantId");


CREATE UNIQUE INDEX IF NOT EXISTS "IX_Tenants_TenantCode" ON "Tenants" ("TenantCode");
